const items = $input.all();

return items.map((item) => {
  const body = item.json.body ?? {};
  const errors = [];

  const callId = String(body.call_id ?? "").trim();
  const leadId = String(body.lead_id ?? "").trim();
  const transcript = String(body.transcript ?? "").trim();
  const language = String(body.language ?? "de").trim();

  if (!callId) {
    errors.push("Missing call_id");
  }

  if (!leadId) {
    errors.push("Missing lead_id");
  }

  if (!transcript) {
    errors.push("Missing transcript");
  } else if (transcript.length < 50) {
    errors.push("Transcript is too short");
  }

  if (errors.length > 0) {
  return {
    json: {
      call_id: callId || null,
      lead_id: leadId || null,
      validation_status: "invalid",
      errors: errors
    }
  };
}

  return {
    json: {
      call_id: callId,
      lead_id: leadId,
      call_date: body.call_date ?? null,
      language,
      duration_seconds: body.duration_seconds ?? null,
      transcript,
      validation_status: "valid",
      received_at: new Date().toISOString()
    }
  };
});

const items = $input.all();

return items.map((item) => {
  // Extract the JSON text returned by Gemini
  const parts = item.json.content?.parts ?? [];

  const rawText = parts
    .map((part) => part.text ?? "")
    .join("\n")
    .trim();

  if (!rawText) {
    throw new Error("Gemini returned an empty response");
  }

  // Remove optional Markdown code fences
  const cleanedText = rawText
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/, "")
    .trim();

  let analysis;

  try {
    analysis = JSON.parse(cleanedText);
  } catch (error) {
    throw new Error(
      `Invalid JSON returned by Gemini: ${error.message}`
    );
  }

  if (
    !analysis ||
    typeof analysis !== "object" ||
    Array.isArray(analysis)
  ) {
    throw new Error("AI response must be a JSON object");
  }

  // Required text fields
  const requiredStrings = [
    "call_id",
    "lead_id",
    "interest_level",
    "sentiment",
    "summary",
    "next_action"
  ];

  for (const field of requiredStrings) {
    if (
      typeof analysis[field] !== "string" ||
      !analysis[field].trim()
    ) {
      throw new Error(`Invalid or missing field: ${field}`);
    }
  }

  const allowedInterest = [
    "high",
    "medium",
    "low",
    "none"
  ];

  const allowedSentiment = [
    "positive",
    "neutral",
    "negative"
  ];

  if (!allowedInterest.includes(analysis.interest_level)) {
    throw new Error("Invalid interest_level");
  }

  if (!allowedSentiment.includes(analysis.sentiment)) {
    throw new Error("Invalid sentiment");
  }

  if (
    !Number.isInteger(analysis.lead_score) ||
    analysis.lead_score < 0 ||
    analysis.lead_score > 100
  ) {
    throw new Error("lead_score must be an integer from 0 to 100");
  }

  if (typeof analysis.follow_up_required !== "boolean") {
    throw new Error("follow_up_required must be a boolean");
  }

  // Confirm AI IDs match the validated webhook input
  const original = $("Validate Call Data").first().json;

  if (
    analysis.call_id !== original.call_id ||
    analysis.lead_id !== original.lead_id
  ) {
    throw new Error("AI response IDs do not match input data");
  }

  return {
    json: {
      call_id: analysis.call_id,
      lead_id: analysis.lead_id,
      interest_level: analysis.interest_level,
      lead_score: analysis.lead_score,
      sentiment: analysis.sentiment,
      summary: analysis.summary.trim(),
      next_action: analysis.next_action.trim(),
      follow_up_required: analysis.follow_up_required,
      analyzed_at: new Date().toISOString(),
      model_provider: "google_gemini",
      analysis_status: "completed"
    }
  };
});

